  function makeTextureStarSource(width, height) {
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    context.fillStyle = "#e8e8e8";
    context.fillRect(0, 0, width, height);
    const centerX = width / 2;
    const centerY = height / 2;
    const outerX = width * 0.43;
    const outerY = height * 0.43;
    const waistX = width * 0.07;
    const waistY = height * 0.07;
    const gradient = context.createLinearGradient(centerX - outerX, centerY - outerY, centerX + outerX, centerY + outerY);
    gradient.addColorStop(0, "#050505");
    gradient.addColorStop(0.52, "#242424");
    gradient.addColorStop(1, "#050505");
    context.fillStyle = gradient;
    context.beginPath();
    context.moveTo(centerX, centerY - outerY);
    context.bezierCurveTo(centerX + waistX * 0.18, centerY - waistY * 1.9, centerX + waistX * 1.9, centerY - waistY * 0.18, centerX + outerX, centerY);
    context.bezierCurveTo(centerX + waistX * 1.9, centerY + waistY * 0.18, centerX + waistX * 0.18, centerY + waistY * 1.9, centerX, centerY + outerY);
    context.bezierCurveTo(centerX - waistX * 0.18, centerY + waistY * 1.9, centerX - waistX * 1.9, centerY + waistY * 0.18, centerX - outerX, centerY);
    context.bezierCurveTo(centerX - waistX * 1.9, centerY - waistY * 0.18, centerX - waistX * 0.18, centerY - waistY * 1.9, centerX, centerY - outerY);
    context.closePath();
    context.fill();
    return canvas;
  }
