    ctx.drawImage(backdrop, 0, 0);
    releaseCanvas(backdrop);
    const sheetWidth = 220;
    const sheetHeight = sheetWidth * OUTPUT_HEIGHT / OUTPUT_WIDTH;
    const sheetX = (canvas.width - sheetWidth) / 2;
