    const canvasHeight = canvas.offsetHeight;
    if (!canvasWidth || !canvasHeight) return;
    target.style.left = canvas.offsetLeft + canvasWidth * PHOTO_RECT.x / OUTPUT_WIDTH + "px";
    target.style.top = canvas.offsetTop + canvasHeight * PHOTO_RECT.y / OUTPUT_HEIGHT + "px";
    target.style.width = canvasWidth * PHOTO_RECT.w / OUTPUT_WIDTH + "px";
    target.style.height = canvasHeight * PHOTO_RECT.h / OUTPUT_HEIGHT + "px";
    target.style.visibility = "visible";
